import type { Artist } from '../models/artist.model';
import { bundledImageFor, photoCount } from './artist-images.generated';

/**
 * Photos for every artist come from Wikimedia Commons and are generated by
 * `scripts/build-catalogue.mjs` into `artist-images.generated.ts` — see
 * `docs/PHOTO_CREDITS.md` for how they are licensed and attributed.
 *
 * This file exists for the gaps and the exceptions:
 *
 * 1. **Override a generated photo** — map the artist id to your own image.
 * 2. **Fill a gap** — artists with no Commons photo fall back to generated
 *    artwork, and you can point them at a licensed file of your own instead.
 *
 * Either a bundled path (`assets/artists/foo.jpg`) or an absolute URL works.
 * The artist id is the slugified name — `AC/DC` -> `ac-dc`, `Beyoncé` -> `beyonce`.
 */
const MANUAL_OVERRIDES: Readonly<Record<string, string>> = {
  // 'some-artist': 'assets/artists/some-artist.jpg',
};

/**
 * Resolves an artist's photo, or `undefined` to fall back to generated artwork.
 * Resolution order: explicit artist photo, then your override, then Commons.
 */
export function imageFor(artist: Artist): string | undefined {
  return artist.image ?? MANUAL_OVERRIDES[artist.id] ?? bundledImageFor(artist);
}

/** How many artists ship with a bundled Commons photo. */
export function bundledPhotoCount(): number {
  return photoCount();
}
